package com.paytrace.decision; import com.paytrace.incident.*; import com.paytrace.payment.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class OfflineDecisionIntelligence implements DecisionIntelligencePort { public DecisionAssessment assess(PaymentView payment,List<Incident> incidents){var primary=incidents.stream().filter(i->i.incidentType()!=IncidentType.NORMAL).findFirst().map(Incident::incidentType).orElse(IncidentType.NORMAL);boolean captured=payment.canonicalState()==PaymentState.CAPTURED||payment.canonicalState()==PaymentState.SETTLED;return new DecisionAssessment(primary,captured?0.97:0.05,!captured,incidents.stream().anyMatch(i->i.severity()==Severity.HIGH),captured, captured?0.75:0.10,"offline-deterministic-stub");} }
